var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City scene not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel comp = null;
Sim.Jobs.JobActiveHUD hud = null;
foreach (var r in roots) {
    if (comp == null) comp = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (hud == null) hud = r.GetComponentInChildren<Sim.Jobs.JobActiveHUD>(true);
}
var soComp = new UnityEditor.SerializedObject(comp);
soComp.Update();
Debug.Log("[Verify] ResultPanel.root=" + (soComp.FindProperty("root").objectReferenceValue?.name ?? "NULL"));
Debug.Log("[Verify] ResultPanel.ratingLabel=" + (soComp.FindProperty("ratingLabel").objectReferenceValue?.name ?? "NULL"));
Debug.Log("[Verify] ResultPanel.scoreLabel=" + (soComp.FindProperty("scoreLabel").objectReferenceValue?.name ?? "NULL"));
Debug.Log("[Verify] ResultPanel.breakdownLabel=" + (soComp.FindProperty("breakdownLabel").objectReferenceValue?.name ?? "NULL"));
Debug.Log("[Verify] ResultPanel.closeButton=" + (soComp.FindProperty("closeButton").objectReferenceValue?.name ?? "NULL"));
if (hud != null) {
    var soHud = new UnityEditor.SerializedObject(hud);
    soHud.Update();
    Debug.Log("[Verify] HUD.sortProgressRoot=" + (soHud.FindProperty("sortProgressRoot").objectReferenceValue?.name ?? "NULL"));
    Debug.Log("[Verify] HUD.sortProgressText=" + (soHud.FindProperty("sortProgressText").objectReferenceValue?.name ?? "NULL"));
}
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
Debug.Log("[Verify] Scene saved.");
